<?php
declare(strict_types=1);
require __DIR__.'/admin-common.php';require __DIR__.'/electric-common.php';
try{[$db,$admin]=pdg_admin_session();electric_bootstrap($db);
 if($_SERVER['REQUEST_METHOD']==='GET'){$query=substr(trim((string)($_GET['q']??'')),0,100);$enquiries=$db->query('SELECT id,public_ref,customer_name,email,phone,project_name,material_json,materials_cents,missing_prices,labour_cents,status,created_at FROM pdg_electric_enquiries ORDER BY id DESC LIMIT 100')->fetchAll();pdg_answer(200,['products'=>electric_products($db,$query,true),'enquiries'=>$enquiries,'busbarRates'=>array_values(electric_rates($db))]);}
 if($_SERVER['REQUEST_METHOD']!=='POST')pdg_answer(405,['error'=>'method_not_allowed']);$raw=file_get_contents('php://input',false,null,0,8193);if(strlen($raw)>8192)pdg_answer(413,['error'=>'request_too_large']);$in=json_decode($raw,true);if(!is_array($in))pdg_answer(422,['error'=>'invalid_input']);
 switch($in['action']??''){
 case 'price':$sku=$in['sku']??'';if(!is_string($sku)||strlen($sku)>40)throw new InvalidArgumentException('sku');$price=electric_money($in['price']??null);$q=$db->prepare('SELECT sku FROM pdg_electric_products WHERE sku=?');$q->execute([$sku]);if(!$q->fetch())pdg_answer(404,['error'=>'not_found']);$q=$db->prepare('UPDATE pdg_electric_products SET price_cents=? WHERE sku=?');$q->execute([$price,$sku]);break;
 case 'rate':$w=$in['width']??0;$t=$in['thickness']??0;$price=electric_money($in['price']??null);if(!is_numeric($w)||!is_numeric($t)||$w<2||$w>100||$t<1||$t>20||$price===null)throw new InvalidArgumentException('rate');$key=sprintf('%.2fx%.2f',(float)$w,(float)$t);$q=$db->prepare('INSERT INTO pdg_electric_busbar_rates(profile_key,width_mm,thickness_mm,price_per_m_cents) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE price_per_m_cents=VALUES(price_per_m_cents)');$q->execute([$key,$w,$t,$price]);break;
 case 'labour':$id=$in['id']??null;$price=electric_money($in['price']??null);if(!is_int($id)||$id<1||$price===null)throw new InvalidArgumentException('labour');$q=$db->prepare('SELECT id FROM pdg_electric_enquiries WHERE id=?');$q->execute([$id]);if(!$q->fetch())pdg_answer(404,['error'=>'not_found']);$q=$db->prepare("UPDATE pdg_electric_enquiries SET labour_cents=?,labour_admin=?,status='reviewed' WHERE id=?");$q->execute([$price,$admin,$id]);break;
 default:throw new InvalidArgumentException('action');}pdg_answer(200,['ok'=>true]);
}catch(InvalidArgumentException $e){pdg_answer(422,['error'=>'invalid_input']);}catch(Throwable $e){pdg_answer(503,['error'=>'service_unavailable']);}
